--
-- Table structure for table 'BT_BANK_TYPE'
--
BEGIN
    EXECUTE IMMEDIATE 'DROP TABLE BT_BANK_TYPE';
EXCEPTION WHEN OTHERS THEN NULL;
END;
/

CREATE TABLE BT_BANK_TYPE (
    ID VARCHAR2(32) NOT NULL PRIMARY KEY,
    BANK_TYPE CHAR(4) NULL,
    TYPE_NAME VARCHAR2(100) NULL,
    BANK_PREFIX VARCHAR2(20) NULL,
    RMK CLOB NULL,
    VALID_SIGN CHAR(1) NULL,
    CREATE_DATE DATE NULL,
    CREATE_BY VARCHAR2(32) NULL,
    UPDATE_DATE DATE NULL,
    UPDATE_BY VARCHAR2(32) NULL,
    IS_SYSTEM CHAR(1) NULL,
    NETBANK_CFCA_DATE DATE NULL,
    BANK_NAME_PREFIX VARCHAR2(64) NULL,
    IS_DOMESTIC_BANK CHAR(1) DEFAULT '1' NULL,
    icon CLOB NULL,
    GRADIENT VARCHAR2(200) NULL,
    REMIT_METHOD VARCHAR2(10) NULL,
    BANK_KIND VARCHAR2(32) NULL,
    WHETHER_CONNECT_BANK VARCHAR2(32) NULL,
    IS_THIRD_PARTY CHAR(1) DEFAULT '0' NULL,
    CREDIT_CONTRACT_REQUIRED CHAR(1) NULL,
    TENANT_ID VARCHAR2(32) NULL
);

COMMENT ON TABLE BT_BANK_TYPE IS '银行类型表';
COMMENT ON COLUMN BT_BANK_TYPE.BANK_TYPE IS '银行类型编码';
COMMENT ON COLUMN BT_BANK_TYPE.RMK IS '备注';
COMMENT ON COLUMN BT_BANK_TYPE.VALID_SIGN IS '有效标志';
COMMENT ON COLUMN BT_BANK_TYPE.CREDIT_CONTRACT_REQUIRED IS '授信合同是否必须';
COMMENT ON COLUMN BT_BANK_TYPE.TENANT_ID IS '租户ID';

CREATE INDEX IDX_BT_BANK_TYPE_BANK_PREFIX ON BT_BANK_TYPE (BANK_PREFIX);
CREATE INDEX IDX_BT_BANK_TYPE_TENANT_ID ON BT_BANK_TYPE (TENANT_ID);

